#[derive(Arbitrary, Debug)]
struct FuzzMessage {
    id: u32,
    timestamp: u64,
    payload_len: u8,  // cap at 255
    payload_bytes: Vec<u8>,
}

fuzz_target!(|data: &[u8]| {
    let mut unstructured = Unstructured::new(data);
    if let Ok(fuzz_msg) = unstructured.arbitrary::<FuzzMessage>() {
        let payload = String::from_utf8(fuzz_msg.payload_bytes).ok();
        let msg = Message {
            id: fuzz_msg.id,
            timestamp: fuzz_msg.timestamp,
            payload: payload.unwrap_or_default(),
        };
        let bytes = encode_message(&msg);
        let decoded = decode_message(&bytes).unwrap();
        assert_eq!(msg, decoded);
    }
});
```

### Strategy 3: Differential Fuzzing

Compare two implementations with the same input:

```rust
fuzz_target!(|data: &[u8]| {
    let result_a = parse_v1(data);
    let result_b = parse_v2(data);
    assert_eq!(result_a, result_b);
});
```

